//! Runtime support for Zig code generated by `zant-tsx` from `.tsx`
//! components (`docs/tsx.md`). Hand-written Zig code rarely needs it.
const std = @import("std");
const ui = @import("ui.zig");

/// Heap memory of string state; it lives as long as the state value.
const allocator = std.heap.smp_allocator;

/// String state (`useState<string>`): starts as a literal and owns a copy
/// of every later value.
pub const String = struct {
    initial: []const u8 = "",
    owned: ?[]u8 = null,

    pub fn get(self: *const String) []const u8 {
        return self.owned orelse self.initial;
    }

    /// Replaces the value with a copy of `value` (which may alias the
    /// current one).
    pub fn set(self: *String, value: []const u8) void {
        const copy = allocator.dupe(u8, value) catch @panic("Zant UI: out of memory while setting string state");
        if (self.owned) |old| allocator.free(old);
        self.owned = copy;
    }

    pub fn deinit(self: *String) void {
        if (self.owned) |old| allocator.free(old);
        self.owned = null;
    }
};

/// Template literals, string `+` and JSX text with expressions: formatted
/// into the frame arena (valid until the next frame, like every node).
pub fn fmt(comptime format: []const u8, args: anytype) []const u8 {
    return std.fmt.allocPrint(ui.frameAllocator(), format, args) catch
        @panic("Zant UI: out of memory while formatting a string");
}

/// Children with conditional entries (`{cond && <X/>}`): drops the nulls.
pub fn nodes(items: []const ?ui.Node) []const ui.Node {
    const out = ui.frameAllocator().alloc(ui.Node, items.len) catch
        @panic("Zant UI: out of memory while building children");
    var n: usize = 0;
    for (items) |item| {
        if (item) |node| {
            out[n] = node;
            n += 1;
        }
    }
    return out[0..n];
}

test "string state owns its values" {
    var s = String{ .initial = "Zant" };
    defer s.deinit();
    try std.testing.expectEqualStrings("Zant", s.get());
    s.set("UI");
    try std.testing.expectEqualStrings("UI", s.get());
    s.set(s.get()[0..1]); // aliasing the current value
    try std.testing.expectEqualStrings("U", s.get());
}

test "nodes drops null children" {
    ui.beginFrame();
    defer ui.endFrame();
    const a = ui.text("a", .{});
    const b = ui.text("b", .{});
    const out = nodes(&.{ a, null, b, null });
    try std.testing.expectEqual(@as(usize, 2), out.len);
    try std.testing.expectEqual(b.element, out[1].element);
    try std.testing.expectEqualStrings("x=3 on", fmt("x={d} {s}", .{ 3, "on" }));
}
